const KEY='baile-flow';
const seed={settings:{modalidades:['Samba','Ritmos Brasileiros'],niveles:['Básico','Técnico'],direcciones:['La Casa del Deportista','Semillarbol','Av. La Tirana 3524','Genaro Gallo 2742'],metodosPago:['Transferencia bancaria','Efectivo'],creditoDias:90,defaultValues:{samba:24000,ritmos:20000,ritmosCombo:15000,avulsaSamba:8000,avulsaRitmos:7000,particular:20000}},students:[],turmas:[],lessons:[],cycles:[],payments:[],expenses:[],singleClasses:[]};
function load(){try{let x=localStorage.getItem(KEY);if(x)return JSON.parse(x);for(const k of ['baile-flow-v9','baile-flow-v8','baile-flow-v7','baile-flow-v6','baile-flow-v5','baile-flow-v4']){x=localStorage.getItem(k);if(x){const d=JSON.parse(x);localStorage.setItem(KEY,JSON.stringify(d));return d}}}catch(e){}return JSON.parse(JSON.stringify(seed))}
function normalize(d){d=d&&typeof d==='object'?d:{};d.settings=d.settings&&typeof d.settings==='object'?d.settings:{};for(const k of ['modalidades','niveles','direcciones','metodosPago'])if(!Array.isArray(d.settings[k]))d.settings[k]=seed.settings[k].slice();if(!Number.isFinite(Number(d.settings.creditoDias)))d.settings.creditoDias=90;d.settings.defaultValues={...seed.settings.defaultValues,...(d.settings.defaultValues||{})};for(const k of ['students','turmas','lessons','cycles','payments','expenses','singleClasses'])if(!Array.isArray(d[k]))d[k]=[];d.students.forEach(s=>{if(!s.id)s.id=uid('stu_');if(s.active===undefined)s.active=true;if(s.scholarship===undefined)s.scholarship=false;if(s.blacklisted===undefined)s.blacklisted=false});d.turmas.forEach(t=>{if(!t.id)t.id=uid('tur_');if(t.active===undefined)t.active=true;if(t.futureWindow===undefined)t.futureWindow=4});d.lessons.forEach(l=>{if(!l.id)l.id=uid('les_');if(l.cancelled===undefined)l.cancelled=false;if(!Array.isArray(l.history))l.history=[];l.duration=Number(l.duration)||durationFor(l.modality||d.turmas.find(t=>t.id===l.turmaId)?.modality);l.manualEdited=!!l.manualEdited;l.source='turma'});d.cycles.forEach(c=>{if(!c.id)c.id=uid('cyc_');c.lessonIds=Array.isArray(c.lessonIds)?c.lessonIds:[];c.lessonCount=Math.max(1,Number(c.lessonCount||c.targetLessonCount||c.lessonIds.length||4));c.targetLessonCount=c.lessonCount;c.scheduleLocked=!!c.scheduleLocked;c.attendance=c.attendance&&typeof c.attendance==='object'?c.attendance:{};c.makeupIds=Array.isArray(c.makeupIds)?c.makeupIds:[];c.excludedLessonIds=Array.isArray(c.excludedLessonIds)?c.excludedLessonIds:[]});d.payments.forEach(p=>{if(!p.id)p.id=uid('pay_')});d.expenses.forEach(p=>{if(!p.id)p.id=uid('exp_')});return d}
let db=normalize(load()),view='inicio',studentFilters={q:'',status:'all',level:'all',modality:'all'},homeMonth=new Date(),financeMonth=todayIso().slice(0,7),financeFilter='all',financeYear=new Date().getFullYear(),financeSeries={received:true,expenses:true,result:true};
const $=id=>document.getElementById(id);const save=()=>{dedupeAllMakeups();localStorage.setItem(KEY,JSON.stringify(db))};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=n=>'$'+Number(n||0).toLocaleString('es-CL');
const parseMoney=s=>{let t=String(s??'').trim().replace(/\s/g,'').replace(/\$/g,'');if(t.includes(',')&&t.includes('.'))t=t.replace(/\./g,'').replace(',','.');else if(t.includes('.'))t=t.replace(/\./g,'');else if(t.includes(','))t=t.replace(',','.');return Number(t)||0};
const dateCL=s=>{if(!s)return'';const d=new Date(s+'T12:00:00');return d.toLocaleDateString('es-CL',{day:'2-digit',month:'2-digit',year:'numeric'})};
const uid=p=>p+Date.now()+Math.random().toString(36).slice(2,7);
const dayMap={Lunes:1,Martes:2,Miércoles:3,Jueves:4,Viernes:5,Sábado:6,Domingo:0};const dayShort={Lunes:'Lun',Martes:'Mar',Miércoles:'Mié',Jueves:'Jue',Viernes:'Vie',Sábado:'Sáb',Domingo:'Dom'};
function durationFor(mod){return /samba/i.test(mod||'')&&!/ritmos/i.test(mod||'')?90:60}
function nav(){return `<div class="nav">${[['inicio','Inicio'],['alumnas','Alumnas'],['turmas','Turmas'],['finanzas','Finanzas'],['mas','Más']].map(([k,t])=>`<button class="${view===k?'active':''}" onclick="go('${k}')">${t}</button>`).join('')}</div>`}
function render(){try{document.body.innerHTML=`<div class="app"><div class="top"><h1>Baile Flow</h1><small>Samba con Luana · gestión · V15</small></div>${nav()}<main class="main">${page()}</main></div>`}catch(e){console.error(e);document.body.innerHTML=`<div class="app"><div class="top"><h1>Baile Flow</h1></div><main class="main"><div class="card"><div class="title">Baile Flow</div><p>Hubo un problema al cargar la pantalla.</p></div></main></div>`}}
function page(){if(view==='inicio')return home();if(view==='alumnas')return students();if(view==='turmas')return turmas();if(view==='finanzas')return finance();return more()}
function home(){const active=db.students.filter(s=>s.active&&!s.blacklisted).length,pending=cyclesPendingPayment(),near=cyclesNearEnd(),month=homeMonth;const monthLessons=uniqueLessons(db.lessons.filter(l=>!l.cancelled&&sameMonth(l.date,month)).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)));const bdays=db.students.filter(s=>s.birthday&&!s.blacklisted&&birthdayWithin30(s.birthday)).sort((a,b)=>nextBirthdayDate(a.birthday).localeCompare(nextBirthdayDate(b.birthday)));return `<div class="grid"><button class="stat statBtn" onclick="openStudentFilter('active')">Alumnas activas<b>${active}</b></button><button class="stat statBtn" onclick="showDashboardList('makeups')">Reposiciones<b>${pendingMakeups()}</b></button><button class="stat statBtn" onclick="showDashboardList('pending')">Pagos pendientes<b>${pending}</b></button><button class="stat statBtn" onclick="showDashboardList('near')">Ciclos por vencer<b>${near}</b></button><button class="stat statBtn" onclick="showDashboardList('completed')">Ciclo concluido — acción<b>${cyclesAwaitingAction()}</b></button></div><div class="card"><div class="row"><div class="title">Calendario</div><div class="monthNav"><button class="secondary" onclick="changeHomeMonth(-1)">‹</button><b>${month.toLocaleDateString('es-CL',{month:'long',year:'numeric'})}</b><button class="secondary" onclick="changeHomeMonth(1)">›</button></div></div>${calendarHtml(month,monthLessons)}</div><div class="card"><div class="title">Aniversariantes · próximos 30 días</div>${bdays.length?bdays.map(s=>`<div class="listitem"><b>${esc(displayName(s.name))}</b> <span class="tag">${esc(s.birthday.slice(8,10)+'/'+s.birthday.slice(5,7))}</span></div>`).join(''):'<div class="empty">No hay aniversariantes en los próximos 30 días.</div>'}</div>`}
function dashboardLesson(l){return `<button class="listitem clickable" onclick="lessonDetail('${l.id}')"><b>${esc(turmaName(l.turmaId))}</b><br><span class="muted">${esc(dayShort[getDayName(l.date)]||getDayName(l.date))} · ${esc(l.time)} · ${esc(l.location)} · ${l.duration||durationFor(l.modality)} min</span>${l.rescheduledFrom?`<br><span class="tag">Reprogramada</span>`:''}</button>`}
function showDashboardList(kind){if(kind==='makeups')return openDashboardModal('Reposiciones',db.cycles.flatMap(c=>(c.makeupIds||[]).filter(m=>makeupIsPending(c,m)).map(m=>({c,m}))));if(kind==='pending')return openDashboardModal('Pagos pendientes',db.cycles.filter(c=>isActiveStudent(c.studentId)&&!db.students.find(s=>s.id===c.studentId)?.scholarship&&cycleBalance(c)>0));if(kind==='completed')return openDashboardModal('Ciclo concluido — aguardando acción',db.cycles.filter(c=>isActiveStudent(c.studentId)&&cycleNeedsAction(c)));return openDashboardModal('Ciclos por vencer',db.cycles.filter(c=>isActiveStudent(c.studentId)&&!hasPaidNextCycle(c)&&!cycleCompleted(c)&&(()=>{const l=lastLesson(c);return l&&l.date>=todayIso()&&l.date<=addDays(todayIso(),7)})()))}
function openDashboardModal(title,items){let body='';if(items.length){body=items.map(x=>{if(x.c&&x.m)return `<div class="listitem"><b>${esc(studentName(x.c.studentId))}</b><br><span class="muted">Reposición de ${dateCL(makeupDate(x.m))}${x.m.extendedUntil?' · extendida hasta '+dateCL(x.m.extendedUntil):''}</span><div class="actions"><button class="secondary" onclick="makeupForm('${x.c.id}','${x.m.id}')">Gestionar</button><button class="secondary" onclick="studentDetail('${x.c.studentId}')">Abrir</button></div></div>`;const c=x.c||x,last=lastLesson(c);if(title.includes('concluido'))return `<div class="listitem"><b>${esc(studentName(c.studentId))}</b><br><span class="muted">${esc(cycleModality(c))} · Última aula: ${last?dateCL(last.date):'-'}</span><div class="actions"><button class="secondary" onclick="studentDetail('${c.studentId}')">Abrir</button><button onclick="cycleForm('${c.studentId}')">+ Nuevo ciclo</button><button class="secondary" onclick="deactivateStudent('${c.studentId}')">Inactivar</button></div></div>`;return `<button class="listitem clickable" onclick="studentDetail('${c.studentId}')"><b>${esc(studentName(c.studentId))}</b><br><span class="muted">${esc(cycleModality(c))} · Última aula: ${last?dateCL(last.date):'-'}${c.scholarship?' · Bolsista':''}</span></button>`}).join('')}else body='<div class="empty">No hay registros.</div>';openModal(`<div class="row"><div class="title">${title}</div><button class="close" onclick="closeModal()">×</button></div>${body}`)}
function deactivateStudent(id){const s=db.students.find(x=>x.id===id);if(!s)return;s.active=false;save();closeModal();render()}
function lessonKey(l){return `${l.date}|${l.time}|${l.location}`}
function uniqueLessons(ls){const seen=new Set();return ls.filter(l=>{const k=lessonKey(l);if(seen.has(k))return false;seen.add(k);return true})}
function calendarHtml(month,lessons){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),start=(first.getDay()||7)-1,days=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];let h='<div class="calendar">'+days.map(d=>`<div class="calHead">${d}</div>`).join('');for(let i=0;i<start;i++)h+='<div class="calCell emptyCal"></div>';for(let d=1;d<=last.getDate();d++){const iso=localIso(y,m,d),ls=lessons.filter(l=>l.date===iso);h+=`<button class="calCell ${ls.length?'hasLesson':''}" onclick="dayLessons('${iso}')"><span>${d}</span>${ls.length?`<i>${ls.length}</i>`:''}</button>`}return h+'</div>'}
function dayLessons(iso){const ls=uniqueLessons(db.lessons.filter(l=>l.date===iso&&!l.cancelled).sort((a,b)=>a.time.localeCompare(b.time)));openModal(`<div class="row"><div class="title">Clases · ${dateCL(iso)}</div><button class="close" onclick="closeModal()">×</button></div>${ls.length?ls.map(l=>dashboardLesson(l)).join(''):'<div class="empty">No hay clases registradas.</div>'}`)}
function changeHomeMonth(n){homeMonth=new Date(homeMonth.getFullYear(),homeMonth.getMonth()+n,1);render()}
function sameMonth(iso,d){return iso&&iso.startsWith(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}function localIso(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}function todayIso(){const d=new Date();return localIso(d.getFullYear(),d.getMonth(),d.getDate())}
function birthdayWithin30(b){const d=nextBirthdayDate(b),now=todayIso();return d>=now&&d<=addDays(now,30)}function nextBirthdayDate(b){const now=new Date(),md=String(b).slice(5,10),y=now.getFullYear();let d=`${y}-${md}`;if(d<todayIso())d=`${y+1}-${md}`;return d}
function makeupDate(m){return m.scheduledDate||db.lessons.find(l=>l.id===m.lessonId)?.date||m.date||''}
function dedupeMakeupsForCycle(c){const seen=new Set();const out=[];(c.makeupIds||[]).forEach(m=>{const key=makeupDate(m)||m.lessonId;if(seen.has(key))return;seen.add(key);out.push(m)});c.makeupIds=out}
function dedupeAllMakeups(){const seenStudentDate=new Set();db.cycles.forEach(c=>{dedupeMakeupsForCycle(c);c.makeupIds=c.makeupIds.filter(m=>{const d=makeupDate(m);if(!d)return true;const key=c.studentId+'|'+d;if(seenStudentDate.has(key))return false;seenStudentDate.add(key);return true})})}
function pendingMakeups(){dedupeAllMakeups();let changed=false;const n=db.cycles.reduce((sum,c)=>sum+(c.makeupIds||[]).filter(m=>makeupIsPending(c,m)).length,0);if(changed)save();return n}
function isActiveStudent(id){const s=db.students.find(x=>x.id===id);return !!s&&s.active&&!s.blacklisted}
function cycleBalance(c){return Math.max(0,Number(c.value||0)-db.payments.filter(p=>p.cycleId===c.id).reduce((a,p)=>a+Number(p.amount||0),0))}
function cycleLessons(c){return (Array.isArray(c.lessonIds)?c.lessonIds:[]).map(id=>db.lessons.find(l=>l.id===id)).filter(Boolean).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))}
function lastLesson(c){return cycleLessons(c).slice(-1)[0]}
function hasPaidNextCycle(c){return db.cycles.some(n=>n.id!==c.id&&n.studentId===c.studentId&&cycleModality(n)===cycleModality(c)&&n.startDate>c.startDate&&cycleBalance(n)<=0)}
function cycleDone(c){const ids=Array.isArray(c.lessonIds)?c.lessonIds:[];return ids.filter(id=>['Presente','Faltó','Reposición'].includes(attendanceFor(c,id))).length}
function cycleCompleted(c){const ls=cycleLessons(c);return ls.length>0&&cycleDone(c)>=ls.length&&ls[ls.length-1].date<todayIso()}
function cycleNeedsAction(c){return cycleCompleted(c)&&!hasNewerCycle(c)}
function hasNewerCycle(c){return db.cycles.some(n=>n.id!==c.id&&n.studentId===c.studentId&&cycleModality(n)===cycleModality(c)&&n.startDate>c.startDate)}
function cyclesPendingPayment(){return db.cycles.filter(c=>isActiveStudent(c.studentId)&&!db.students.find(s=>s.id===c.studentId)?.scholarship&&cycleBalance(c)>0).length}
function cyclesNearEnd(){return db.cycles.filter(c=>isActiveStudent(c.studentId)&&!hasPaidNextCycle(c)&&!cycleCompleted(c)&&(()=>{const l=lastLesson(c);return l&&l.date>=todayIso()&&l.date<=addDays(todayIso(),7)})()).length}
function cyclesAwaitingAction(){return db.cycles.filter(c=>isActiveStudent(c.studentId)&&cycleNeedsAction(c)).length}
function displayName(n){const p=String(n||'').trim().split(/\s+/);return p.slice(0,2).join(' ')}
function normalizeSearch(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-CL')}
function cycleEndDate(c){const l=lastLesson(c);return l?.date||c.startDate||''}
function cycleIsCurrent(c){return !!cycleEndDate(c)&&cycleEndDate(c)>=todayIso()}
function makeupIsPending(c,m){if(!m||m.status==='used'||m.status==='expired')return false;const end=cycleEndDate(c);if(m.extendedUntil)return m.extendedUntil>=todayIso();return cycleIsCurrent(c)}
function makeupWasExtended(c,m){return !!m?.extendedUntil&&m.extendedUntil>=todayIso()}

function enrollmentLabel(s){const byMod={};db.cycles.filter(c=>c.studentId===s.id).forEach(c=>{const t=db.turmas.find(x=>x.id===c.turmaId);if(!t)return;const key=t.modality;const prev=byMod[key];if(!prev||String(c.startDate).localeCompare(String(prev.startDate))>0)byMod[key]={startDate:c.startDate,level:t.level||''}});const vals=Object.entries(byMod).sort((a,b)=>a[0].localeCompare(b[0],'es')).map(([m,v])=>`${m}${v.level?' · '+v.level:''}`);if(!vals.length)return '<span class="muted">Sin matrícula</span>';return vals.map(v=>`<div>${esc(v)}</div>`).join('')}
function students(){const activeSearch=document.activeElement?.id==='studentSearch';let arr=db.students.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'es',{sensitivity:'base'}));const f=studentFilters;arr=arr.filter(s=>(!f.q||normalizeSearch(s.name).includes(normalizeSearch(f.q)))&&(f.status==='all'||(f.status==='active'&&!s.blacklisted&&s.active)||(f.status==='inactive'&&!s.active)||(f.status==='blacklist'&&s.blacklisted))&&(f.level==='all'||db.cycles.some(c=>c.studentId===s.id&&db.turmas.find(t=>t.id===c.turmaId)?.level===f.level))&&(f.modality==='all'||db.cycles.some(c=>c.studentId===s.id&&db.turmas.find(t=>t.id===c.turmaId)?.modality===f.modality)));return `<div class="row"><div class="title">Alumnas</div><button onclick="studentForm()">+ Nueva</button></div><div class="card"><div class="filters"><input id="studentSearch" placeholder="Buscar por nombre..." value="${esc(f.q)}" oninput="studentFilters.q=this.value;render();setTimeout(()=>{const x=document.getElementById('studentSearch');if(x){x.focus();x.setSelectionRange(x.value.length,x.value.length)}},0)"><select onchange="studentFilters.status=this.value;render()"><option value="all" ${f.status==='all'?'selected':''}>Todas</option><option value="active" ${f.status==='active'?'selected':''}>Activas</option><option value="inactive" ${f.status==='inactive'?'selected':''}>Inactivas</option><option value="blacklist" ${f.status==='blacklist'?'selected':''}>Lista negra</option></select><select onchange="studentFilters.level=this.value;render()"><option value="all">Todos los niveles</option>${db.settings.niveles.map(x=>`<option value="${esc(x)}" ${f.level===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select onchange="studentFilters.modality=this.value;render()"><option value="all">Todas las modalidades</option>${db.settings.modalidades.map(x=>`<option value="${esc(x)}" ${f.modality===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="card">${arr.length?arr.map(s=>`<div class="listitem"><div class="row"><div><b>${esc(displayName(s.name))}</b><br><span class="enroll">${enrollmentLabel(s)}</span><br><span class="muted">${esc(s.phone||'')} · ${s.blacklisted?'Lista negra':s.active?'Activa':'Inactiva'}${s.scholarship?' · Bolsista':''}</span></div><button class="secondary" onclick="studentDetail('${s.id}')">Abrir</button></div></div>`).join(''):'<div class="empty">No hay alumnas con estos filtros.</div>'}</div>`}
function openStudentFilter(status){studentFilters={q:'',status,level:'all',modality:'all'};go('alumnas')}
function studentForm(id=''){const s=db.students.find(x=>x.id===id)||{name:'',phone:'',birthday:'',entryDate:'',observations:'',active:true,scholarship:false,blacklisted:false};openModal(`<div class="row"><div class="title">${id?'Editar':'Nueva'} alumna</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Nombre completo</label><input id="f_name" value="${esc(s.name)}"></div><div class="field"><label>Teléfono</label><input id="f_phone" value="${esc(s.phone)}"></div><div class="field"><label>Fecha de nacimiento</label><input id="f_bday" type="date" value="${esc(s.birthday)}"></div><div class="field"><label>Fecha de ingreso</label><input id="f_entry" type="date" value="${esc(s.entryDate)}"></div><div class="field"><label>Estado</label><select id="f_active"><option value="1" ${s.active?'selected':''}>Activa</option><option value="0" ${!s.active?'selected':''}>Inactiva</option></select></div><div class="field"><label>Tipo</label><select id="f_scholar"><option value="0" ${!s.scholarship?'selected':''}>Regular</option><option value="1" ${s.scholarship?'selected':''}>Bolsista</option></select></div><div class="field"><label>Lista negra</label><select id="f_black"><option value="0" ${!s.blacklisted?'selected':''}>No</option><option value="1" ${s.blacklisted?'selected':''}>Sí</option></select></div><div class="field"><label>Observaciones</label><textarea id="f_obs">${esc(s.observations)}</textarea></div><div class="actions"><button onclick="saveStudent('${id}')">Guardar</button>${id?`<button class="danger" onclick="deleteStudent('${id}')">Excluir aluna</button>`:''}</div>`)}
function saveStudent(id){const old=db.students.find(x=>x.id===id);const s={id:id||uid('stu_'),name:$('f_name').value.trim(),phone:$('f_phone').value.trim(),birthday:$('f_bday').value,entryDate:$('f_entry').value,observations:$('f_obs').value.trim(),active:$('f_active').value==='1',scholarship:$('f_scholar').value==='1',blacklisted:$('f_black').value==='1'};if(!s.name)return alert('Ingresa el nombre.');if(id)Object.assign(old,s);else db.students.push(s);save();closeModal();render()}
function deleteStudent(id){const s=db.students.find(x=>x.id===id);if(!s)return;if(!confirm(`¿Excluir definitivamente a ${s.name}? Esta acción elimina su ficha, ciclos y pagos asociados.`))return;const cycleIds=db.cycles.filter(c=>c.studentId===id).map(c=>c.id);db.students=db.students.filter(x=>x.id!==id);db.cycles=db.cycles.filter(c=>c.studentId!==id);db.payments=db.payments.filter(p=>p.studentId!==id&&!cycleIds.includes(p.cycleId));save();closeModal();render()}
function studentDetail(id){const s=db.students.find(x=>x.id===id);if(!s)return alert('No se encontró esta alumna.');const modalities=[...new Set(db.cycles.filter(c=>c.studentId===id).map(c=>cycleModality(c)))];const pays=db.payments.filter(p=>p.studentId===id).sort((a,b)=>b.date.localeCompare(a.date));openModal(`<div class="row"><div class="title">${esc(s.name)}</div><button class="close" onclick="closeModal()">×</button></div><div class="profileHead"><div><b>${s.blacklisted?'Lista negra':s.active?'Activa':'Inactiva'}${s.scholarship?' · Bolsista':''}</b><div class="muted">${esc(s.phone||'')} · Nacimiento: ${s.birthday?esc(s.birthday.slice(8,10)+'/'+s.birthday.slice(5,7)):''}</div></div><div class="actions"><button class="secondary" onclick="studentForm('${id}')">Editar</button><button class="secondary" onclick="cycleForm('${id}')">+ Ciclo</button><button onclick="paymentForm('${id}')">Registrar pago</button></div></div><div class="tabs">${modalities.length?modalities.map((m,i)=>`<button class="secondary" onclick="showStudentModality('${id}','${esc(m)}')">${esc(m)}</button>`).join(''):''}<button class="secondary" onclick="showStudentModality('${id}','all')">Todos</button><button class="secondary" onclick="$('studentPayments').scrollIntoView({behavior:'smooth'})">Pagos</button></div><div id="studentModalityContent">${studentModalityContent(id,'all')}</div><div class="card" id="studentPayments"><div class="title">Historial de pagos</div>${pays.length?pays.map(p=>`<div class="listitem"><b>${money(p.amount)}</b> · ${dateCL(p.date)} · ${esc(p.method)}${p.cycleId?`<br><span class="muted">Ciclo ${(()=>{const pc=db.cycles.find(c=>c.id===p.cycleId);return pc?dateCL(pc.startDate):'anterior (conservado)'})()}</span>`:''}<div class="actions"><button class="secondary" onclick="paymentForm('${id}','${p.id}')">Editar</button><button class="danger" onclick="deletePayment('${p.id}')">Eliminar</button></div></div>`).join(''):'<div class="empty">Sin pagos.</div>'}</div>`)}
function showStudentModality(id,m){const el=$('studentModalityContent');if(el)el.innerHTML=studentModalityContent(id,m)}
function studentModalityContent(id,m){const cycles=db.cycles.filter(c=>c.studentId===id&&(m==='all'||cycleModality(c)===m)).sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')));return cycles.length?cycles.map(c=>cycleCard(c)).join(''):'<div class="card"><div class="empty">Sin ciclos registrados en esta modalidad.</div></div>'}
function cycleModality(c){return db.turmas.find(t=>t.id===c.turmaId)?.modality||c.modality||'Sin modalidad'}
function cycleNumber(c){const m=cycleModality(c);return db.cycles.filter(x=>x.studentId===c.studentId&&cycleModality(x)===m).sort((a,b)=>String(a.startDate||'').localeCompare(String(b.startDate||''))).findIndex(x=>x.id===c.id)+1}
function attendanceFor(c,lid){return c.attendance?.[lid]||'No registrado'}
function cycleCard(c){const t=db.turmas.find(x=>x.id===c.turmaId),lessonIds=Array.isArray(c.lessonIds)?c.lessonIds:[],lessons=lessonIds.map(id=>db.lessons.find(l=>l.id===id)).filter(Boolean).sort((a,b)=>a.date.localeCompare(b.date)),done=cycleDone(c),paid=db.payments.filter(p=>p.cycleId===c.id).reduce((a,p)=>a+Number(p.amount||0),0),billed=lessonIds.filter(id=>!(c.excludedLessonIds||[]).includes(id)).length,closed=cycleCompleted(c)||done>=lessonIds.length&&lessonIds.length>0;return `<div class="card cycleCard"><div class="cycleTop"><div><b>Ciclo ${cycleNumber(c)} · ${closed?'Concluído':'Em andamento'}</b></div><button class="secondary" onclick="cycleForm('${c.studentId}','${c.id}')">✏️ Editar</button></div><div class="historyDates">${lessons.map(l=>`<span class="presenceDot ${attendanceFor(c,l.id)==='Presente'?'p':attendanceFor(c,l.id)==='Faltó'?'a':''}" title="${dateCL(l.date)} · ${attendanceFor(c,l.id)}">${dateCL(l.date).slice(0,5)}</span>`).join(' | ')}</div><div class="muted">Inicio: ${dateCL(c.startDate)} · Última aula: ${lessons.length?dateCL(lessons[lessons.length-1].date):'-'}</div><div class="cycleSummary"><span>Clases: <b>${billed}/${lessonIds.length}</b></span><span>Valor: <b>${money(c.value)}</b></span><span>Pagado: <b>${money(paid)}</b></span><span>Pendiente: <b>${money(Math.max(0,c.value-paid))}</b></span></div><div class="turmaMini">${t?`${esc(t.modality)}${t.level?' · '+esc(t.level):''} · ${esc(dayShort[t.weekday]||t.weekday)} · ${esc(t.time)} · ${esc(t.location)} · ${durationFor(t.modality)} min`:'Turma no encontrada'}</div><details><summary>Ver clases</summary><div class="lessonList">${lessonIds.map((lid,i)=>lessonRow(c,lid,i+1)).join('')}</div></details></div>`}
function lessonRow(c,lid,n){const l=db.lessons.find(x=>x.id===lid);if(!l)return '';const status=attendanceFor(c,lid),cls=status==='Presente'?'present':status==='Faltó'?'absent':status==='Reposición'?'makeup':'pending',excluded=(c.excludedLessonIds||[]).includes(lid);return `<div class="lessonRow"><div class="lessonCount">${n}/${c.lessonIds.length}</div><div class="lessonInfo"><b>${l?dateCL(l.date):'-'}</b><div class="lessonMeta">${l?esc(dayShort[getDayName(l.date)]||getDayName(l.date)):'-'} · ${esc(l?.time||'')} · ${esc(l?.location||'')} · ${l?.duration||60} min</div>${excluded?'<span class="tag">No cobrada</span>':''}${l?.cancelled?`<span class="tag dangerTag">Cancelada</span>`:''}${l?.rescheduledFrom?`<span class="tag">Reprogramada</span>`:''}</div><select class="attendance ${cls}" onchange="setAttendance('${c.id}','${lid}',this.value)"><option ${status==='No registrado'?'selected':''}>No registrado</option><option ${status==='Presente'?'selected':''}>Presente</option><option ${status==='Faltó'?'selected':''}>Faltó</option><option ${status==='Reposición'?'selected':''}>Reposición</option></select><div class="lessonActions"></div></div>`}
function getDayName(iso){const d=new Date(iso+'T12:00:00');return Object.keys(dayMap).find(k=>dayMap[k]===d.getDay())||''}
function setAttendance(cycleId,lessonId,next){const c=db.cycles.find(x=>x.id===cycleId);if(!c)return;const current=attendanceFor(c,lessonId);c.attendance[lessonId]=next;if(next==='Faltó'&&current!=='Faltó'&&!c.makeupIds.some(m=>makeupDate(m)===db.lessons.find(l=>l.id===lessonId)?.date&&m.status!=='used'&&m.status!=='expired'))c.makeupIds.push({id:uid('mk_'),lessonId,createdAt:todayIso(),status:'pending'});if(current==='Faltó'&&next!=='Faltó')c.makeupIds=c.makeupIds.filter(m=>m.lessonId!==lessonId||m.status==='used');save();studentDetail(c.studentId)}
function editCycleLesson(cycleId,lessonId){const c=db.cycles.find(x=>x.id===cycleId),l=db.lessons.find(x=>x.id===lessonId);if(!c||!l)return;openModal(`<div class="row"><div class="title">Editar clase</div><button class="close" onclick="closeModal()">×</button></div><div class="notice">Editar manualmente cambia solo esta clase y guarda la nueva fecha, hora y local. No reprograma las demás.</div><div class="field"><label>Fecha</label><input id="cl_date" type="date" value="${esc(l.date)}"></div><div class="field"><label>Hora</label><input id="cl_time" type="time" value="${esc(l.time)}"></div><div class="field"><label>Dirección</label><select id="cl_loc">${db.settings.direcciones.map(x=>`<option ${x===l.location?'selected':''}>${esc(x)}</option>`).join('')}</select></div><button onclick="saveCycleLesson('${c.studentId}','${c.turmaId}','${lessonId}')">Guardar corrección</button>`)}
function saveCycleLesson(studentId,turmaId,lessonId){const l=db.lessons.find(x=>x.id===lessonId);if(!l)return;const date=$('cl_date').value,time=$('cl_time').value,loc=$('cl_loc').value;if(!date)return alert('Ingresa la fecha.');l.history=l.history||[];if(date!==l.date||time!==l.time||loc!==l.location)l.history.push({type:'edicion_manual',from:{date:l.date,time:l.time,location:l.location},to:{date,time,location:loc},date:todayIso()});l.date=date;l.time=time;l.location=loc;l.manualEdited=true;l.duration=l.duration||durationFor(db.turmas.find(t=>t.id===turmaId)?.modality);save();closeModal();studentDetail(studentId)}
function reprogramLesson(lessonId){const l=db.lessons.find(x=>x.id===lessonId);if(!l)return;openModal(`<div class="row"><div class="title">Reprogramar aula</div><button class="close" onclick="closeModal()">×</button></div><div class="notice"><b>Importante:</b> cambiar esta fecha desplazará por el mismo número de días las clases posteriores de esta turma. Esto afecta a todas las alumnas cuyos ciclos usan esas clases.</div><div class="field"><label>Nueva fecha</label><input id="rp_date" type="date" value="${esc(l.date)}"></div><div class="field"><label>Nueva hora</label><input id="rp_time" type="time" value="${esc(l.time)}"></div><div class="field"><label>Nueva dirección</label><select id="rp_loc">${db.settings.direcciones.map(x=>`<option ${x===l.location?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Motivo</label><textarea id="rp_reason" placeholder="Ej.: feriado, cierre del recinto..."></textarea></div><button onclick="saveReprogram('${lessonId}')">Guardar reprogramación</button>`)}
function saveReprogram(lessonId){const l=db.lessons.find(x=>x.id===lessonId);if(!l)return;const newDate=$('rp_date').value,reason=$('rp_reason').value.trim();if(!newDate||!reason)return alert('Completa la nueva fecha y el motivo.');const oldDate=l.date,delta=diffDays(oldDate,newDate),turmaId=l.turmaId;const affected=db.lessons.filter(x=>x.turmaId===turmaId&&x.id!==lessonId&&x.date>oldDate&&!x.manualEdited).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));if(!Array.isArray(l.history))l.history=[];l.history.push({type:'reprogramacion',from:{date:l.date,time:l.time,location:l.location},to:{date:newDate,time:$('rp_time').value,location:$('rp_loc').value},reason,date:todayIso(),shiftDays:delta});l.rescheduledFrom={date:l.date,time:l.time,location:l.location};l.date=newDate;l.time=$('rp_time').value;l.location=$('rp_loc').value;affected.forEach(x=>{x.history=x.history||[];x.history.push({type:'desplazamiento',from:{date:x.date,time:x.time,location:x.location},to:{date:addDays(x.date,delta),time:x.time,location:x.location},reason:`Desplazamiento automático por reprogramación de ${dateCL(oldDate)}`,date:todayIso(),shiftDays:delta});x.date=addDays(x.date,delta)});save();closeModal();turmaDetail(turmaId)}
function diffDays(a,b){const x=new Date(a+'T12:00:00'),y=new Date(b+'T12:00:00');return Math.round((y-x)/86400000)}
function cycleDefault(studentId,turmaId){const t=db.turmas.find(x=>x.id===turmaId),s=db.students.find(x=>x.id===studentId);if(!t)return 0;if(/samba/i.test(t.modality)&&!/ritmos/i.test(t.modality))return db.settings.defaultValues.samba;if(/ritmos/i.test(t.modality))return s&&db.cycles.some(c=>c.studentId===studentId&&/samba/i.test(cycleModality(c))&&!/ritmos/i.test(cycleModality(c)))?db.settings.defaultValues.ritmosCombo:db.settings.defaultValues.ritmos;return 0}
function cycleForm(studentId,id=''){const old=db.cycles.find(c=>c.id===id),firstTurma=old?db.turmas.find(t=>t.id===old.turmaId):db.turmas.find(t=>t.active),value=old?.baseValue??old?.value??cycleDefault(studentId,firstTurma?.id||''),ids=old?(Array.isArray(old.lessonIds)?old.lessonIds:[]):[];const count=old?.lessonCount||ids.length||4;openModal(`<div class="row"><div class="title">${id?'Editar':'Nuevo'} ciclo</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Turma</label><select id="c_turma" onchange="previewCycleValue('${studentId}','${id}')">${db.turmas.filter(t=>t.active).map(t=>`<option value="${t.id}" ${t.id===old?.turmaId?'selected':''}>${esc(turmaLabel(t))}</option>`).join('')}</select></div><div class="field"><label>Fecha de inicio</label><input id="c_date" type="date" value="${esc(old?.startDate||todayIso())}"></div><div class="field"><label>Cantidad de clases</label><div class="row"><input id="c_count" type="number" min="1" max="31" value="${count}"><button type="button" class="secondary" onclick="addCycleLessonCount()">+ 1 aula extra</button></div><div class="muted">El ciclo parte con 4 aulas, pero puedes reducir o agregar aulas. La cantidad define las aulas generadas y el valor proporcional.</div></div><div class="field"><label>Valor base de 4 clases</label><input id="c_value" inputmode="decimal" value="${Number(value||0).toLocaleString('es-CL')}"></div>${id?`<div class="notice">Puedes marcar clases como no cobradas. También puedes editar manualmente fecha, hora y local de una clase sin reprogramar las demás.</div><div id="cycleBilling">${ids.map(lid=>{const l=db.lessons.find(x=>x.id===lid),ex=(old.excludedLessonIds||[]).includes(lid);return `<label class="checkRow"><input type="checkbox" data-lid="${lid}" ${!ex?'checked':''}> ${l?dateCL(l.date):''} · ${l?.time||''} <span class="muted">Cobrar</span></label>`}).join('')}</div>`:'<div class="notice">El valor se calcula proporcionalmente según la cantidad de clases.</div>'}<button onclick="saveCycle('${studentId}','${id}')">Guardar ciclo</button>${id?`<button class="danger" onclick="deleteCycle('${id}')">Excluir ciclo</button>`:''}`)}
function previewCycleAmount(){}
function addCycleLessonCount(){const input=$('c_count');if(!input)return;input.value=Math.min(31,(Number(input.value)||4)+1)}
function previewCycleValue(studentId,id){const t=db.turmas.find(t=>t.id===$('c_turma').value);if(!id&&$('c_value'))$('c_value').value=cycleDefault(studentId,t?.id||'').toLocaleString('es-CL')}
function lessonSort(a,b){return a.date.localeCompare(b.date)||String(a.time||'').localeCompare(String(b.time||''))}
function ensureTurmaFutureLessons(turmaId,minimum=4){const t=db.turmas.find(x=>x.id===turmaId);if(!t||!t.active)return [];const today=todayIso();let valid=db.lessons.filter(l=>l.turmaId===turmaId&&!l.cancelled&&l.date>=today).sort(lessonSort);let cursor=new Date(today+'T12:00:00'),guard=0;while(valid.length<minimum&&guard<370){if(cursor.getDay()===dayMap[t.weekday]){const iso=cursor.toISOString().slice(0,10);let l=db.lessons.find(x=>x.turmaId===turmaId&&x.date===iso);if(!l){l={id:uid('les_'),turmaId,date:iso,time:t.time,location:t.location,duration:durationFor(t.modality),cancelled:false,history:[],manualEdited:false,source:'turma'};db.lessons.push(l)}if(!l.cancelled&&!valid.some(x=>x.id===l.id))valid.push(l)}cursor.setDate(cursor.getDate()+1);guard++}return valid.sort(lessonSort)}
function validTurmaLessons(turmaId,fromDate=''){const t=db.turmas.find(x=>x.id===turmaId);if(t)ensureTurmaFutureLessons(turmaId,4);return db.lessons.filter(l=>l.turmaId===turmaId&&!l.cancelled&&(!fromDate||l.date>=fromDate)).sort(lessonSort)}
function ensureCycleLessons(c,saveIt=true){const t=db.turmas.find(x=>x.id===c.turmaId);if(!t)return Array.isArray(c.lessonIds)?c.lessonIds:[];const target=Math.max(1,Number(c.lessonCount||c.targetLessonCount||c.lessonIds?.length||4));const oldIds=Array.isArray(c.lessonIds)?c.lessonIds:[];const oldLessons=oldIds.map(id=>db.lessons.find(l=>l.id===id)).filter(Boolean);const keep=oldLessons.filter(l=>l.cancelled?l.date<todayIso()||attendanceFor(c,l.id)!=='No registrado':l.date<todayIso()||attendanceFor(c,l.id)!=='No registrado');let ids=keep.map(l=>l.id);const lastDate=keep.reduce((m,l)=>!m||l.date>m?l.date:m,'');const start=lastDate?addDays(lastDate,1):(c.startDate||todayIso());const pool=validTurmaLessons(c.turmaId,start);for(const l of pool){if(ids.length>=target)break;if(!ids.includes(l.id))ids.push(l.id)}c.lessonIds=ids.slice(0,target);c.lessonCount=target;c.targetLessonCount=target;if(saveIt)save();return c.lessonIds}
function syncTurmaCycles(turmaId){db.cycles.filter(c=>c.turmaId===turmaId).forEach(c=>{if(c.startDate)ensureCycleLessons(c,false)});}
function ensureAllTurmaLessons(){let changed=false;db.turmas.filter(t=>t.active).forEach(t=>{const before=db.lessons.length;ensureTurmaFutureLessons(t.id,4);if(db.lessons.length!==before)changed=true});if(changed)save()}
function countBilled(c){const ids=Array.isArray(c.lessonIds)?c.lessonIds:[];return ids.filter(id=>!(c.excludedLessonIds||[]).includes(id)).length}
function cycleBasePerClass(c){return Number(c.baseValue||c.value||0)/4}
function saveCycle(studentId,id){const old=db.cycles.find(c=>c.id===id);const c=old||{id:uid('cyc_'),studentId,lessonIds:[],attendance:{},makeupIds:[],excludedLessonIds:[]};const newTurma=$('c_turma').value,newStart=$('c_date').value,target=Math.max(1,Math.min(31,Number($('c_count').value)||4));if(!newStart||!newTurma)return alert('Completa la turma y la fecha.');const structuralChange=!!old&&(old.turmaId!==newTurma||old.startDate!==newStart);if(structuralChange){const oldIds=Array.isArray(c.lessonIds)?c.lessonIds:[];const keep=oldIds.filter(lid=>{const l=db.lessons.find(x=>x.id===lid);return l&&(l.date<todayIso()||attendanceFor(c,lid)!=='No registrado')});c.lessonIds=keep;c.excludedLessonIds=(c.excludedLessonIds||[]).filter(lid=>keep.includes(lid));c.scheduleLocked=false}c.studentId=studentId;c.turmaId=newTurma;c.startDate=newStart;c.lessonCount=target;c.targetLessonCount=target;c.scheduleLocked=false;ensureTurmaFutureLessons(newTurma,4);ensureCycleLessons(c,false);const raw=parseMoney($('c_value').value);if(!raw)return alert('Ingresa un valor.');c.baseValue=raw;c.excludedLessonIds=c.excludedLessonIds||[];if(id){const checked=[...document.querySelectorAll('#cycleBilling input[data-lid]:checked')].map(x=>x.dataset.lid);c.excludedLessonIds=ensureCycleLessons(c,false).filter(x=>!checked.includes(x))}c.value=Math.round(raw*(countBilled(c)/4));c.attendance=c.attendance||{};c.makeupIds=c.makeupIds||[];if(!old)db.cycles.push(c);save();closeModal();studentDetail(studentId)}
function deleteCycle(id){const c=db.cycles.find(x=>x.id===id);if(!c)return;const linked=db.payments.filter(p=>p.cycleId===id).length;if(!confirm(`¿Excluir este ciclo? Se quitará solo el ciclo de la alumna. Las aulas oficiales de la turma y ${linked?`los ${linked} pago(s) registrado(s)`:'los pagos registrados'} se conservarán intactos. Podrás crear un ciclo nuevo desde cero.`))return;const studentId=c.studentId;db.cycles=db.cycles.filter(x=>x.id!==id);save();closeModal();studentDetail(studentId)}
function addPreviousLesson(cycleId){const c=db.cycles.find(x=>x.id===cycleId);if(!c)return;openModal(`<div class="row"><div class="title">Registrar clase anterior</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Fecha</label><input id="pl_date" type="date"></div><div class="field"><label>Hora</label><input id="pl_time" type="time" value="${esc(db.turmas.find(t=>t.id===c.turmaId)?.time||'19:30')}"></div><div class="field"><label>Dirección</label><select id="pl_loc">${db.settings.direcciones.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><button onclick="savePreviousLesson('${cycleId}')">Guardar clase</button>`)}
function savePreviousLesson(cycleId){const c=db.cycles.find(x=>x.id===cycleId),t=db.turmas.find(t=>t.id===c.turmaId);const l={id:uid('les_'),turmaId:c.turmaId,date:$('pl_date').value,time:$('pl_time').value,location:$('pl_loc').value,duration:durationFor(t?.modality),cancelled:false,history:[]};if(!l.date)return alert('Ingresa la fecha.');db.lessons.push(l);if(c.lessonIds.length<4)c.lessonIds.push(l.id);else c.lessonIds[c.lessonIds.length-1]=l.id;save();closeModal();studentDetail(c.studentId)}
function turmas(){const order={Lunes:1,Martes:2,Miércoles:3,Jueves:4,Viernes:5,Sábado:6,Domingo:7};const sorted=db.turmas.slice().sort((a,b)=>(order[a.weekday]||9)-(order[b.weekday]||9)||String(a.time).localeCompare(String(b.time)));return `<div class="row"><div class="title">Turmas</div><button onclick="turmaForm()">+ Nueva</button></div><div class="card">${sorted.length?sorted.map(t=>`<div class="listitem"><div class="row"><div><b>${esc(turmaLabel(t))}</b><br><span class="muted">${t.active?'Activa':'Inactiva'} · Capacidad ${t.capacity}</span></div><button class="secondary" onclick="turmaDetail('${t.id}')">Abrir turma</button></div></div>`).join(''):'<div class="empty">No hay turmas.</div>'}</div>`}
function turmaLabel(t){return `${t.modality}${t.level?' · '+t.level:''} · ${t.weekday} ${t.time} · ${t.location}`}
function turmaName(id){const t=db.turmas.find(x=>x.id===id);return t?turmaLabel(t):'Turma no encontrada'}
function turmaForm(id=''){const t=db.turmas.find(x=>x.id===id)||{modality:db.settings.modalidades[0]||'',level:'',location:db.settings.direcciones[0]||'',weekday:'Lunes',time:'19:30',capacity:15,active:true};const days=Object.keys(dayMap),times=['08:00','08:30','09:00','09:30','10:00','10:30','11:00','11:30','12:00','18:00','18:30','19:00','19:30','20:00','20:30','21:00'];openModal(`<div class="row"><div class="title">${id?'Editar':'Nueva'} turma</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Modalidad</label><select id="t_mod">${db.settings.modalidades.map(x=>`<option ${x===t.modality?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Nivel</label><select id="t_level"><option value="">Sin nivel</option>${db.settings.niveles.map(x=>`<option ${x===t.level?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Dirección</label><select id="t_loc">${db.settings.direcciones.map(x=>`<option ${x===t.location?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Día</label><select id="t_day">${days.map(x=>`<option ${x===t.weekday?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Hora</label><select id="t_time">${times.map(x=>`<option ${x===t.time?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Duración</label><div class="notice">${durationFor(t.modality)} minutos (${durationFor(t.modality)===90?'1h30':'1h'})</div></div><div class="field"><label>Capacidad</label><input id="t_cap" type="number" min="1" value="${t.capacity}"></div><button onclick="saveTurma('${id}')">Guardar</button>`)}
function saveTurma(id){const t={id:id||uid('tur_'),modality:$('t_mod').value,level:$('t_level').value,location:$('t_loc').value,weekday:$('t_day').value,time:$('t_time').value,capacity:Number($('t_cap').value)||1,active:true};if(id)Object.assign(db.turmas.find(x=>x.id===id),t);else db.turmas.push(t);ensureTurmaFutureLessons(t.id,4);save();closeModal();render()}
function turmaDetail(id){const t=db.turmas.find(x=>x.id===id);if(!t)return;ensureTurmaFutureLessons(id,4);const ls=db.lessons.filter(l=>l.turmaId===id).sort((a,b)=>b.date.localeCompare(a.date)||String(b.time).localeCompare(String(a.time)));openModal(`<div class="row"><div class="title">${esc(turmaLabel(t))}</div><button class="close" onclick="closeModal()">×</button></div><div class="profileHead"><b>${t.active?'Activa':'Inactiva'}</b><div class="muted">Duración: ${durationFor(t.modality)} min · Capacidad: ${t.capacity}</div></div><div class="actions"><button class="secondary" onclick="turmaForm('${id}')">Editar turma</button><button onclick="lessonForm('${id}')">+ Crear aula</button><button class="secondary" onclick="rebuildTurmaCycles('${id}')">Reconstruir ciclos</button></div><div class="card"><div class="title">Aulas</div>${ls.length?ls.map(l=>`<button class="listitem clickable lessonListItem" onclick="lessonDetail('${l.id}')"><div><b>${dateCL(l.date)} · ${esc(l.time)}</b><br><span class="muted">${esc(l.location)} · ${l.duration||durationFor(t.modality)} min</span>${l.cancelled?'<br><span class="tag dangerTag">Cancelada</span>':''}${l.rescheduledFrom?'<br><span class="tag">Reprogramada</span>':''}</div><span>›</span></button><div class="lessonListActions">${!l.cancelled?`<button class="secondary" onclick="cancelLesson('${l.id}');event.stopPropagation()">Cancelar aula</button>`:''}<button class="danger" onclick="deleteLesson('${l.id}');event.stopPropagation()">Excluir aula</button></div>`).join(''):'<div class="empty">Todavía no hay aulas.</div>'}</div>`)}
function rebuildTurmaCycles(turmaId){const cycles=db.cycles.filter(c=>c.turmaId===turmaId);if(!cycles.length)return alert('No hay ciclos de alumnas para reconstruir en esta turma.');if(!confirm('Se reconstruirán solo las clases futuras no registradas de esta turma. Se conservarán alumnas, pagos, historial y asistencias ya registradas. ¿Continuar?'))return;ensureTurmaFutureLessons(turmaId,4);cycles.forEach(c=>{const oldIds=Array.isArray(c.lessonIds)?c.lessonIds:[];const keep=oldIds.filter(lid=>{const l=db.lessons.find(x=>x.id===lid);return l&&(l.date<todayIso()||attendanceFor(c,lid)!=='No registrado')});c.lessonIds=keep;c.excludedLessonIds=(c.excludedLessonIds||[]).filter(lid=>keep.includes(lid));c.makeupIds=(c.makeupIds||[]).filter(m=>c.lessonIds.includes(m.lessonId));ensureCycleLessons(c,false);c.value=Math.round(Number(c.baseValue||c.value||0)*(countBilled(c)/4))});save();turmaDetail(turmaId)}
function lessonDetail(id){const l=db.lessons.find(x=>x.id===id);if(!l)return;const t=db.turmas.find(x=>x.id===l.turmaId);const rows=db.cycles.filter(c=>c.lessonIds.includes(id)&&isActiveStudent(c.studentId)).map(c=>({c,s:db.students.find(s=>s.id===c.studentId)})).sort((a,b)=>a.s.name.localeCompare(b.s.name,'es'));openModal(`<div class="row"><div class="title">${dateCL(l.date)} · ${esc(l.time)}</div><button class="close" onclick="closeModal()">×</button></div><div class="profileHead"><b>${esc(t?turmaLabel(t):'Clase')}</b><div class="muted">${esc(l.location)} · ${l.duration||durationFor(t?.modality)} minutos</div></div><div class="card"><div class="title">Alumnas de esta clase</div>${rows.length?rows.map(({c,s})=>{const st=attendanceFor(c,id),cls=st==='Presente'?'present':st==='Faltó'?'absent':st==='Reposición'?'makeup':'pending';return `<div class="attendanceRow"><div><b>${esc(displayName(s.name))}</b>${s.scholarship?' <span class="tag">Bolsista</span>':''}</div><select class="attendance ${cls}" onchange="setAttendanceFromLesson('${c.id}','${id}',this.value)"><option ${st==='No registrado'?'selected':''}>No registrado</option><option ${st==='Presente'?'selected':''}>Presente</option><option ${st==='Faltó'?'selected':''}>Faltó</option><option ${st==='Reposición'?'selected':''}>Reposición</option></select></div>`}).join(''):'<div class="empty">Ninguna alumna tiene esta clase en su ciclo.</div>'}</div><div class="actions"><button class="secondary" onclick="reprogramLesson('${id}')">↪ Reprogramar</button><button class="secondary" onclick="lessonForm('${l.turmaId}','${id}')">Editar</button></div>`)}
function setAttendanceFromLesson(cycleId,lessonId,next){const c=db.cycles.find(x=>x.id===cycleId);if(!c)return;const current=attendanceFor(c,lessonId);c.attendance[lessonId]=next;if(next==='Faltó'&&current!=='Faltó'&&!c.makeupIds.some(m=>makeupDate(m)===db.lessons.find(l=>l.id===lessonId)?.date&&m.status!=='used'&&m.status!=='expired'))c.makeupIds.push({id:uid('mk_'),lessonId,createdAt:todayIso(),status:'pending'});if(current==='Faltó'&&next!=='Faltó')c.makeupIds=c.makeupIds.filter(m=>m.lessonId!==lessonId||m.status==='used');save();lessonDetail(lessonId)}
function lessonForm(turmaId,id=''){const t=db.turmas.find(x=>x.id===turmaId),old=db.lessons.find(x=>x.id===id)||{date:todayIso(),time:t?.time||'19:30',location:t?.location||'',cancelled:false};openModal(`<div class="row"><div class="title">${id?'Editar':'Crear'} aula</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Fecha</label><input id="l_date" type="date" value="${esc(old.date)}"></div><div class="field"><label>Hora</label><input id="l_time" type="time" value="${esc(old.time)}"></div><div class="field"><label>Dirección</label><select id="l_loc">${db.settings.direcciones.map(x=>`<option ${x===old.location?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="notice">Duración: ${old.duration||durationFor(t?.modality)} minutos.</div><div class="actions"><button onclick="saveLesson('${turmaId}','${id}')">Guardar aula</button>${id?`<button class="secondary" onclick="cancelLesson('${id}')">Cancelar aula</button>`:''}</div>`)}
function saveLesson(turmaId,id){const t=db.turmas.find(x=>x.id===turmaId),l={id:id||uid('les_'),turmaId,date:$('l_date').value,time:$('l_time').value,location:$('l_loc').value,duration:durationFor(t?.modality),cancelled:false,history:[],source:'turma'};if(!l.date)return alert('Ingresa la fecha.');if(id){const old=db.lessons.find(x=>x.id===id);l.cancelled=old.cancelled;l.reason=old.reason;l.history=old.history||[];l.rescheduledFrom=old.rescheduledFrom;l.manualEdited=old.manualEdited;Object.assign(old,l)}else db.lessons.push(l);syncTurmaCycles(turmaId);save();closeModal();turmaDetail(turmaId)}
function cancelLesson(id){const l=db.lessons.find(x=>x.id===id);if(!l||l.cancelled)return;if(l.date<todayIso())return alert('Una clase pasada no se puede cancelar desde esta acción.');const reason=prompt('Motivo de cancelación:');if(reason===null||!reason.trim())return;if(!Array.isArray(l.history))l.history=[];l.history.push({type:'cancelacion',from:{date:l.date,time:l.time,location:l.location},reason:reason.trim(),date:todayIso()});l.cancelled=true;l.reason=reason.trim();syncTurmaCycles(l.turmaId);ensureTurmaFutureLessons(l.turmaId,4);save();turmaDetail(l.turmaId)}
function deleteLesson(id){const l=db.lessons.find(x=>x.id===id);if(!l)return;const linked=db.cycles.filter(c=>Array.isArray(c.lessonIds)&&c.lessonIds.includes(id));if(linked.length){return alert(`No se puede eliminar esta aula porque tiene ${linked.length} alumna(s) vinculada(s). Las alumnas y sus registros se mantienen intactos.`)}if(!confirm(`¿Eliminar definitivamente el aula del ${dateCL(l.date)}?`))return;db.lessons=db.lessons.filter(x=>x.id!==id);save();turmaDetail(l.turmaId)}
function reprogramLesson(lessonId){const l=db.lessons.find(x=>x.id===lessonId);if(!l)return;openModal(`<div class="row"><div class="title">Editar aula excepcionalmente</div><button class="close" onclick="closeModal()">×</button></div><div class="notice">La modificación se hará sobre esta aula de la turma y será la referencia para las alumnas vinculadas a ella. No se modifican otras aulas.</div><div class="field"><label>Fecha</label><input id="rp_date" type="date" value="${esc(l.date)}"></div><div class="field"><label>Hora</label><input id="rp_time" type="time" value="${esc(l.time)}"></div><div class="field"><label>Nueva dirección</label><select id="rp_loc">${db.settings.direcciones.map(x=>`<option ${x===l.location?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Motivo</label><textarea id="rp_reason" placeholder="Ej.: feriado, cierre del recinto..."></textarea></div><button onclick="saveReprogram('${lessonId}')">Guardar cambio</button>`)}
function saveReprogram(lessonId){const l=db.lessons.find(x=>x.id===lessonId);if(!l)return;const newDate=$('rp_date').value,reason=$('rp_reason').value.trim();if(!newDate||!reason)return alert('Completa la nueva fecha y el motivo.');if(!Array.isArray(l.history))l.history=[];l.history.push({type:'edicion_excepcional',from:{date:l.date,time:l.time,location:l.location},to:{date:newDate,time:$('rp_time').value,location:$('rp_loc').value},reason,date:todayIso()});l.rescheduledFrom={date:l.date,time:l.time,location:l.location};l.date=newDate;l.time=$('rp_time').value;l.location=$('rp_loc').value;l.manualEdited=true;syncTurmaCycles(l.turmaId);save();closeModal();turmaDetail(l.turmaId)}
function makeupForm(cycleId,makeupId){const c=db.cycles.find(x=>x.id===cycleId),m=c?.makeupIds?.find(x=>x.id===makeupId);if(!c||!m)return;const end=cycleEndDate(c),valid=makeupIsPending(c,m);if(!valid)return alert('Esta reposición ya no está vigente.');const current=makeupDate(m);openModal(`<div class="row"><div class="title">Gestionar reposición</div><button class="close" onclick="closeModal()">×</button></div><div class="notice">Esta reposición pertenece al ciclo iniciado el ${dateCL(c.startDate)} y es válida hasta ${dateCL(end)}. Si necesitas mantenerla después de esa fecha, debes extenderla manualmente antes del cierre del ciclo.</div><div class="field"><label>Fecha de reposición</label><input id="mk_date" type="date" value="${esc(m.scheduledDate||current)}"></div><div class="field"><label>Extender hasta</label><input id="mk_until" type="date" value="${esc(m.extendedUntil||'')}"><div class="muted">Opcional. Solo puedes registrar una extensión mientras el ciclo siga vigente.</div></div><div class="actions"><button onclick="saveMakeup('${cycleId}','${makeupId}')">Guardar agenda</button><button class="secondary" onclick="markMakeupUsed('${cycleId}','${makeupId}')">Registrar realizada</button></div>`)}
function saveMakeup(cycleId,makeupId){const c=db.cycles.find(x=>x.id===cycleId),m=c?.makeupIds?.find(x=>x.id===makeupId);if(!c||!m)return;const d=$('mk_date').value,until=$('mk_until').value,end=cycleEndDate(c);if(!d)return alert('Ingresa la fecha de reposición.');if(d<todayIso())return alert('La fecha de reposición no puede estar en el pasado.');if(!until&&d>end)return alert('Para agendar después del cierre del ciclo, debes registrar una extensión manual antes de que el ciclo termine.');if(until){if(todayIso()>end)return alert('El ciclo ya terminó; ya no es posible extender esta reposición.');if(until<end||until<d)return alert('La extensión debe cubrir la fecha de reposición y no puede ser anterior al cierre del ciclo.')}m.scheduledDate=d;m.extendedUntil=until||'';m.status='pending';m.history=m.history||[];m.history.push({type:'agenda',date:d,extendedUntil:until||'',savedAt:todayIso()});save();closeModal();render()}
function markMakeupUsed(cycleId,makeupId){const c=db.cycles.find(x=>x.id===cycleId),m=c?.makeupIds?.find(x=>x.id===makeupId);if(!c||!m)return;m.status='used';m.usedAt=todayIso();save();closeModal();render()}
function monthLabel(ym){const [y,m]=ym.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-CL',{month:'long',year:'numeric'})}
function monthShift(ym,n){const [y,m]=ym.split('-').map(Number),d=new Date(y,m-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function financeTotals(ym){
 const payments=Array.isArray(db.payments)?db.payments:[],expenses=Array.isArray(db.expenses)?db.expenses:[];
 const rec=payments.filter(p=>String(p.date||'').slice(0,7)===ym).reduce((a,p)=>a+Number(p.amount||0),0);
 const exp=expenses.filter(p=>String(p.date||'').slice(0,7)===ym).reduce((a,p)=>a+Number(p.amount||0),0);
 return {rec,exp,res:rec-exp};
}
function financeMovements(ym){const mov=[...db.payments.filter(p=>String(p.date||'').slice(0,7)===ym).map(p=>({...p,type:'Pago'})),...db.expenses.filter(p=>String(p.date||'').slice(0,7)===ym).map(p=>({...p,type:'Gasto'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));return financeFilter==='received'?mov.filter(p=>p.type==='Pago'):financeFilter==='expenses'?mov.filter(p=>p.type==='Gasto'):mov}
function setFinanceMonth(ym){financeMonth=ym;financeYear=Number(String(ym).slice(0,4))||financeYear;financeFilter='all';render()}function setFinanceFilter(f){financeFilter=f;render()}
function financeYearData(year){return Array.from({length:12},(_,i)=>{const ym=`${year}-${String(i+1).padStart(2,'0')}`,t=financeTotals(ym);return {...t,ym}})}
function financeChart(year){const data=financeYearData(year),w=760,h=260,pad=42,all=data.flatMap(d=>[d.rec,d.exp,d.res]),max=Math.max(1,...all),min=Math.min(0,...all),range=Math.max(1,max-min),x=i=>pad+i*((w-pad*2)/11),y=v=>h-pad-((v-min)/range)*(h-pad*2);const series=[['received','Recibido','#2563eb',data.map(d=>d.rec)],['expenses','Gastos','#dc2626',data.map(d=>d.exp)],['result','Resultado','#16a34a',data.map(d=>d.res)]].filter(x=>financeSeries[x[0]]);let svg=`<svg viewBox="0 0 ${w} ${h}" class="financeChart" role="img" aria-label="Gráfico financiero anual">`;[0,.25,.5,.75,1].forEach(r=>{const value=min+(range*r),yy=y(value);svg+=`<line x1="${pad}" y1="${yy}" x2="${w-pad}" y2="${yy}" stroke="#ddd"/><text x="4" y="${yy+4}" font-size="11" fill="#666">${money(Math.round(value))}</text>`});data.forEach((d,i)=>svg+=`<text x="${x(i)}" y="${h-12}" text-anchor="middle" font-size="11" fill="#666">${d.ym.slice(5,7)}</text>`);series.forEach(([key,label,color,vals])=>{const pts=vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');svg+=`<polyline fill="none" stroke="${color}" stroke-width="3" points="${pts}"/>`;vals.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="${color}"><title>${label} · ${data[i].ym}: ${money(v)}</title></circle>`)});svg+='</svg>';return svg}
function finance(){const t=financeTotals(financeMonth),mov=financeMovements(financeMonth),years=[...new Set([...db.payments.map(p=>String(p.date||'').slice(0,4)),...db.expenses.map(p=>String(p.date||'').slice(0,4)),String(new Date().getFullYear())].filter(y=>/^\d{4}$/.test(y)))].sort().reverse(),months=[...new Set([...db.payments.map(p=>String(p.date||'').slice(0,7)),...db.expenses.map(p=>String(p.date||'').slice(0,7)),todayIso().slice(0,7)].filter(y=>/^\d{4}-\d{2}$/.test(y)))].sort().reverse();return `<div class="title">Finanzas</div><div class="card financePeriod"><div class="row"><button class="secondary" onclick="setFinanceMonth(monthShift(financeMonth,-1))">‹</button><select onchange="setFinanceMonth(this.value)">${months.map(ym=>`<option value="${ym}" ${ym===financeMonth?'selected':''}>${esc(monthLabel(ym))}</option>`).join('')} </select><button class="secondary" onclick="setFinanceMonth(monthShift(financeMonth,1))">›</button></div></div><div class="grid financeGrid"><button class="stat ${financeFilter==='received'?'selectedStat':''}" onclick="setFinanceFilter('received')">Recibido<b>${money(t.rec)}</b></button><button class="stat ${financeFilter==='expenses'?'selectedStat':''}" onclick="setFinanceFilter('expenses')">Gastos<b>${money(t.exp)}</b></button><button class="stat ${financeFilter==='all'?'selectedStat':''}" onclick="setFinanceFilter('all')">Saldo<b>${money(t.res)}</b></button></div><div class="card"><div class="row"><div class="title">Gráfico anual</div><select onchange="financeYear=Number(this.value);render()">${years.map(y=>`<option value="${y}" ${Number(y)===financeYear?'selected':''}>${y}</option>`).join('')}</select></div><div class="chartToggles"><label><input type="checkbox" ${financeSeries.received?'checked':''} onchange="financeSeries.received=this.checked;render()"> <span class="dotBlue">Recibido</span></label><label><input type="checkbox" ${financeSeries.expenses?'checked':''} onchange="financeSeries.expenses=this.checked;render()"> <span class="dotRed">Gastos</span></label><label><input type="checkbox" ${financeSeries.result?'checked':''} onchange="financeSeries.result=this.checked;render()"> <span class="dotGreen">Resultado</span></label></div>${financeChart(financeYear)}</div><div class="actions"><button onclick="paymentForm()">+ Registrar pago</button><button class="secondary" onclick="expenseForm()">+ Registrar gasto</button></div><div class="card"><div class="row"><div class="title">Movimientos · ${esc(monthLabel(financeMonth))}</div><span class="muted">${financeFilter==='received'?'Solo recibidos':financeFilter==='expenses'?'Solo gastos':'Entradas y salidas'}</span></div>${mov.length?mov.map(p=>`<div class="listitem"><b>${p.type}: ${money(p.amount)}</b><br><span class="muted">${dateCL(p.date)} · ${esc(p.type==='Pago'?studentName(p.studentId):p.category)}</span><div class="actions">${p.type==='Pago'?`<button class="secondary" onclick="paymentForm('${p.studentId}','${p.id}')">Editar</button><button class="danger" onclick="deletePayment('${p.id}')">Eliminar</button>`:`<button class="secondary" onclick="expenseForm('${p.id}')">Editar</button><button class="danger" onclick="deleteExpense('${p.id}')">Eliminar</button>`}</div></div>`).join(''):'<div class="empty">Sin movimientos en este mes.</div>'}</div>`}
function studentName(id){return db.students.find(s=>s.id===id)?.name||'Alumna'}
function paymentEligible(c,currentId=''){return cycleBalance(c)>0||c.id===currentId}function paymentForm(studentId='',id=''){const old=db.payments.find(p=>p.id===id)||{studentId:studentId||db.students[0]?.id||'',cycleId:'',amount:0,date:todayIso(),method:db.settings.metodosPago[0]||'',notes:''};const cycles=db.cycles.filter(c=>c.studentId===old.studentId&&paymentEligible(c,old.cycleId));const oldCycleMissing=!!old.cycleId&&!db.cycles.some(c=>c.id===old.cycleId);openModal(`<div class="row"><div class="title">${id?'Editar':'Registrar'} pago</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Alumna</label><select id="p_student" onchange="refreshPaymentCycles()" data-current-cycle="${esc(old.cycleId||'')}">${db.students.filter(s=>!s.blacklisted).map(s=>`<option value="${s.id}" ${s.id===old.studentId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Ciclo</label><select id="p_cycle"><option value="">Sin ciclo</option>${oldCycleMissing?`<option value="${esc(old.cycleId)}" selected>Ciclo anterior (conservado)</option>`:''}${cycles.map(c=>`<option value="${c.id}" ${c.id===old.cycleId?'selected':''}>${esc(cycleModality(c))} · ${dateCL(c.startDate)} · ${money(c.value)}</option>`).join('')}</select></div><div class="field"><label>Monto</label><input id="p_amount" inputmode="decimal" value="${old.amount||''}"></div><div class="field"><label>Fecha real de pago</label><input id="p_date" type="date" value="${esc(old.date)}"></div><div class="field"><label>Método de pago</label><select id="p_method">${db.settings.metodosPago.map(x=>`<option ${x===old.method?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Notas</label><input id="p_notes" value="${esc(old.notes||'')}"></div><button onclick="savePayment('${id}')">Guardar pago</button>`)}
function refreshPaymentCycles(){const sid=$('p_student').value,el=$('p_cycle'),current=el.dataset.currentCycle||'';const currentExists=current&&db.cycles.some(c=>c.id===current);el.innerHTML='<option value="">Sin ciclo</option>'+(current&&!currentExists?`<option value="${esc(current)}" selected>Ciclo anterior (conservado)</option>`:'')+db.cycles.filter(c=>c.studentId===sid&&paymentEligible(c,current)).map(c=>`<option value="${c.id}" ${c.id===current?'selected':''}>${esc(cycleModality(c))} · ${dateCL(c.startDate)} · ${money(c.value)}</option>`).join('')}
function savePayment(id){const p={id:id||uid('pay_'),studentId:$('p_student').value,cycleId:$('p_cycle').value,amount:parseMoney($('p_amount').value),date:$('p_date').value,method:$('p_method').value,notes:$('p_notes').value};if(!p.amount)return alert('Ingresa el monto.');if(id)Object.assign(db.payments.find(x=>x.id===id),p);else db.payments.push(p);save();closeModal();render()}
function deletePayment(id){if(!confirm('¿Eliminar este pago?'))return;db.payments=db.payments.filter(p=>p.id!==id);save();render()}
function singleClassForm(){openModal(`<div class="row"><div class="title">Registrar clase</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Alumna</label><select id="sc_student">${db.students.filter(s=>!s.blacklisted).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Tipo</label><select id="sc_type"><option>Aula avulsa Samba</option><option>Aula avulsa Ritmos Brasileiros</option><option>Aula particular</option></select></div><div class="field"><label>Fecha</label><input id="sc_date" type="date" value="${todayIso()}"></div><div class="field"><label>Duración</label><div class="notice">Samba 90 min · Ritmos 60 min · Particular 60 min</div></div><div class="field"><label>Valor</label><input id="sc_amount" inputmode="decimal" value="8000"></div><button onclick="saveSingleClass()">Guardar clase</button>`)}
function saveSingleClass(){const type=$('sc_type').value;let amount=8000,duration=90;if(type.includes('Ritmos')){amount=7000;duration=60}if(type.includes('particular')){amount=20000;duration=60}const x={id:uid('sc_'),studentId:$('sc_student').value,type,date:$('sc_date').value,duration,amount:parseMoney($('sc_amount').value)||amount};db.singleClasses.push(x);save();closeModal();render()}
function expenseForm(id=''){const old=db.expenses.find(p=>p.id===id)||{amount:0,date:todayIso(),category:'Arriendo',notes:''};openModal(`<div class="row"><div class="title">${id?'Editar':'Registrar'} gasto</div><button class="close" onclick="closeModal()">×</button></div><div class="field"><label>Categoría</label><input id="e_cat" value="${esc(old.category)}"></div><div class="field"><label>Monto</label><input id="e_amount" inputmode="decimal" value="${old.amount||''}"></div><div class="field"><label>Fecha</label><input id="e_date" type="date" value="${esc(old.date)}"></div><div class="field"><label>Notas</label><input id="e_notes" value="${esc(old.notes||'')}"></div><button onclick="saveExpense('${id}')">Guardar gasto</button>`)}
function saveExpense(id){const p={id:id||uid('exp_'),category:$('e_cat').value.trim(),amount:parseMoney($('e_amount').value),date:$('e_date').value,notes:$('e_notes').value};if(!p.amount)return alert('Ingresa el monto.');if(id)Object.assign(db.expenses.find(x=>x.id===id),p);else db.expenses.push(p);save();closeModal();render()}
function deleteExpense(id){if(!confirm('¿Eliminar este gasto?'))return;db.expenses=db.expenses.filter(p=>p.id!==id);save();render()}
function more(){return `<div class="title">Más · Configuraciones</div><div class="card">${configList('Modalidades','modalidades')}${configList('Niveles','niveles')}${configList('Direcciones','direcciones')}${configList('Métodos de pago','metodosPago')}</div><div class="card"><div class="title">Valores predeterminados</div>${defaultValueForm()}</div><div class="card"><div class="title">Crédito financiero</div><div class="field"><label>Validez máxima (días)</label><input id="creditDays" type="number" value="${db.settings.creditoDias}"></div><button onclick="saveCreditDays()">Guardar</button></div>`}
function defaultValueForm(){const v=db.settings.defaultValues;return `<div class="field"><label>Samba mensual</label><input id="dv_samba" value="${v.samba}"></div><div class="field"><label>Ritmos Brasileiros mensual</label><input id="dv_ritmos" value="${v.ritmos}"></div><div class="field"><label>Ritmos con Samba</label><input id="dv_combo" value="${v.ritmosCombo}"></div><div class="field"><label>Avulsa Samba</label><input id="dv_as" value="${v.avulsaSamba}"></div><div class="field"><label>Avulsa Ritmos</label><input id="dv_ar" value="${v.avulsaRitmos}"></div><div class="field"><label>Particular 60 min</label><input id="dv_part" value="${v.particular}"></div><button onclick="saveDefaultValues()">Guardar valores</button>`}
function saveDefaultValues(){const v=db.settings.defaultValues;v.samba=parseMoney($('dv_samba').value);v.ritmos=parseMoney($('dv_ritmos').value);v.ritmosCombo=parseMoney($('dv_combo').value);v.avulsaSamba=parseMoney($('dv_as').value);v.avulsaRitmos=parseMoney($('dv_ar').value);v.particular=parseMoney($('dv_part').value);save();render()}
function configList(label,key){return `<div class="configBlock"><div class="row"><b>${label}</b><button onclick="addConfig('${key}')">+ Agregar</button></div>${db.settings[key].map((x,i)=>`<div class="row configRow"><span>${esc(x)}</span><div class="actions"><button class="secondary" onclick="editConfig('${key}',${i})">Editar</button><button class="danger" onclick="deleteConfig('${key}',${i})">Eliminar</button></div></div>`).join('')}</div>`}
function addConfig(k){const x=prompt('Nuevo valor:');if(x?.trim()){db.settings[k].push(x.trim());save();render()}}function editConfig(k,i){const x=prompt('Editar:',db.settings[k][i]);if(x?.trim()){db.settings[k][i]=x.trim();save();render()}}function deleteConfig(k,i){const value=db.settings[k][i];if(!confirm(`¿Eliminar «${value}»?`))return;db.settings[k].splice(i,1);save();render()}function saveCreditDays(){db.settings.creditoDias=Number($('creditDays').value)||90;save();render()}
function addDays(iso,n){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}function go(v){view=v;closeModal();render()}function openModal(html){let m=document.querySelector('.modal');if(!m){m=document.createElement('div');m.className='modal';document.body.appendChild(m)}m.innerHTML=`<div class="sheet">${html}</div>`}function closeModal(){document.querySelector('.modal')?.remove()}
// V10 migration: remove only the generated placeholder Angélica Silva, preserving every other student/data record.
(function migrateV10(){if(localStorage.getItem(KEY+'-v10-migrated'))return;const targets=db.students.filter(s=>String(s.name||'').trim().toLocaleLowerCase('es')==='angélica silva'.toLocaleLowerCase('es'));if(targets.length){const ids=targets.map(s=>s.id),cids=db.cycles.filter(c=>ids.includes(c.studentId)).map(c=>c.id);db.students=db.students.filter(s=>!ids.includes(s.id));db.cycles=db.cycles.filter(c=>!ids.includes(c.studentId));db.payments=db.payments.filter(p=>!ids.includes(p.studentId)&&!cids.includes(p.cycleId));save()}localStorage.setItem(KEY+'-v10-migrated','1')})();
ensureAllTurmaLessons();render();
